'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const {join}=require('node:path');
const {tmpdir}=require('node:os');
const {randomUUID}=require('node:crypto');
const {spawnSync}=require('node:child_process');
const {OfflineNotes,ProtectedStore}=require('../reference/offline-notes.cjs');
(async()=>{
 const input=JSON.parse(fs.readFileSync(0,'utf8'));
 const directory=input.directory||fs.mkdtempSync(join(tmpdir(),'fields-http-'));
 const store=new ProtectedStore(directory,input.store_id||randomUUID());
 let lose=false,posts=0;
 const transport=async(path,method,body,auth)=>{
  const headers={Authorization:'Bearer '+auth.token};if(auth.epoch)headers['X-FreeFSM-Session-Epoch']=auth.epoch;if(auth.operation)headers['Operation-ID']=auth.operation;
  if(body!==undefined)headers['Content-Type']='application/json';
  if(path==='/sync/operations')posts++;
  const r=await fetch(input.url+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body)});
  const result={status:r.status,...await r.json()};
  if(lose&&path==='/sync/operations'){lose=false;throw Error('lost committed response');}return result;
 };
 let client=new OfflineNotes(store,transport);
 if(input.restart){
  assert.equal((await client.reconcile(input.operation_id)).state,'accepted');
  assert.equal(posts,0,'fresh process receipt lookup must not submit');return;
 }
 try{
  await client.initialize();await client.authenticate(input.token);await client.synchronize();
  const job=Object.keys((await client.view()).cache)[0];
  const values=['secret field reading','multiline\nreading','12.50','2026-10-15','false','A',['A','B']].map((value,i)=>({definition_id:i+1,value}));
  const first=await client.stageFields(job,values,[]);
  const stale=await client.stageFields(job,[{definition_id:1,value:'stale'},{definition_id:2,value:'must not persist'}],[]);
  assert(!fs.readFileSync(join(directory,'cache')).includes('secret field reading'));
  lose=true;await assert.rejects(client.submitBatch([first]),/lost committed response/);
  const child=spawnSync(process.execPath,[__filename],{input:JSON.stringify({url:input.url,directory,store_id:store.id,restart:true,operation_id:first}),encoding:'utf8',timeout:30000});
  assert.equal(child.status,0,child.stderr);
  client=new OfflineNotes(new ProtectedStore(directory,store.id),transport);
  assert.equal((await client.view()).pending[first].state,'accepted');
  const original=(await client.view()).pending[first].receipt;
  assert.deepEqual({job_id:original.job_id,effect_id:original.effect_id},{job_id:input.job_id,effect_id:first},'safe receipt retains recorded target/effect identity');
  const legacy=await (await fetch(input.url+`/jobs/${job}/custom-fields?operation_id=${first}`,{headers:{Authorization:'Bearer '+input.token}})).json();
  assert.equal(legacy.data.job_id,original.job_id,'legacy and global lookup retain the same recorded target');
  assert.equal(posts,1,'restart and receipt lookup must not submit');
  await client.submitBatch([stale]);assert.equal((await client.view()).pending[stale].receipt.code,'stale_field_revision');
  await client.synchronize();let view=await client.view();
  assert.equal(view.cache[job].custom_fields.history.length,1);
  const revisions=view.cache[job].custom_fields.revisions;
  const repair=await client.repairFields(stale,[{definition_id:1,value:'reviewed repair'}],revisions,[]);
  await client.submitBatch([repair]);await client.synchronize();
  const required=await client.stageFields(job,[{definition_id:5,value:''}],[]);
  await client.submitBatch([required]);assert.equal((await client.view()).pending[required].receipt.reason,'required_field');
  await fetch(input.url+'/__fixture/required',{method:'POST'});await client.synchronize();
  const unrelated=await client.stageFields(job,[{definition_id:1,value:'unrelated required field deferred'}],[]);
  await client.submitBatch([unrelated]);assert.equal((await client.view()).pending[unrelated].state,'accepted');
  await client.synchronize();assert(!(await client.view()).cache[job].custom_fields.values.some(v=>v.definition_id===8),'no default backfill');
  await fetch(input.url+'/__fixture/options',{method:'POST'});await client.synchronize();
  const retained=await client.stageFields(job,[{definition_id:7,value:['A','B']}],[]);
  await client.submitBatch([retained]);assert.equal((await client.view()).pending[retained].state,'accepted');
  assert.equal((await client.view()).pending[retained].receipt.effect_id,undefined,'no-op does not fabricate mutation attribution');
  const option=await client.stageFields(job,[{definition_id:6,value:'B'},{definition_id:2,value:'invalid option partial write'}],[]);
  await client.submitBatch([option]);assert.equal((await client.view()).pending[option].receipt.reason,'retired_option');
  await client.synchronize();assert.equal((await client.view()).cache[job].custom_fields.values.find(v=>v.definition_id===2).value,'multiline\nreading');
  const retired=await client.stageFields(job,[{definition_id:1,value:'never auto replay'}],[]);
  await fetch(input.url+'/__fixture/retire',{method:'POST'});await client.submitBatch([retired]);
  assert.equal((await client.view()).pending[retired].state,'terminal');
  assert.equal((await client.view()).pending[retired].receipt.reason,'retired_field');
  await fetch(input.url+'/__fixture/reactivate',{method:'POST'});await client.synchronize();
  await assert.rejects(client.submitBatch([retired]),/reconciliation_or_review_required/);
  const pending=await client.stageFields(job,[{definition_id:1,value:'purge me'}],[]);
  await fetch(input.url+'/__fixture/remove',{method:'POST'});await client.synchronize();
  view=await client.view();assert.equal(view.pending[pending].state,'purged');assert.equal(Object.keys(view.cache).length,0);
  const safe=(await client.reconcile(first)).receipt;
  assert.equal(safe.code,'accepted');assert.equal(safe.job_id,input.job_id);assert.equal(safe.effect_id,first);
  const fresh=await (await fetch(input.url+'/__fixture/fresh-token',{method:'POST'})).json();
  await client.authenticate(fresh.token);await client.synchronize();
  assert.deepEqual((await client.reconcile(first)).receipt,original,'later changes, scope loss and fresh authentication retain original receipt');
  console.log('PASS protected fields all types, durable receipt-first recovery, atomic stale patch, reviewed repair, retirement/reactivation, synchronized history and scope purge');
 }finally{await store.destroy();fs.rmSync(directory,{recursive:true,force:true});}
})().catch(e=>{console.error(e);process.exitCode=1;});
